insert into occupations (code, title, description, job_zone, median_wage, growth_pct, source_ids) values
  ('11-1021.00', 'General and Operations Managers', 'Plan, direct, or coordinate the operations of public or private sector organizations, overseeing multiple departments or locations. Duties and responsibilities include formulating policies, managing daily operations, and planning the use of materials and human resources, but are too diverse and general in nature to be classified in any one functional area of management or administration, such as personnel, purchasing, or administrative services. Usually manage through subordinate supervisors. Excludes First-Line Supervisors.', 4, 105770, 5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-1031.00', 'Legislators', 'Develop, introduce, or enact laws and statutes at the local, tribal, state, or federal level. Includes only workers in elected positions.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-2011.00', 'Advertising and Promotions Managers', 'Plan, direct, or coordinate advertising policies and programs or produce collateral materials, such as posters, contests, coupons, or giveaways, to create extra interest in the purchase of a product or service for a department, an entire organization, or on an account basis.', 4, 133660, -3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-2021.00', 'Marketing Managers', 'Plan, direct, or coordinate marketing policies and programs, such as determining the demand for products and services offered by a firm and its competitors, and identify potential customers. Develop pricing strategies with the goal of maximizing the firm''s profits or share of the market while ensuring the firm''s customers are satisfied. Oversee product development or monitor trends that indicate the need for new products and services.', 4, 166790, 6.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-2022.00', 'Sales Managers', 'Plan, direct, or coordinate the actual distribution or movement of a product or service to the customer. Coordinate sales distribution by establishing sales territories, quotas, and goals and establish training programs for sales representatives. Analyze sales statistics gathered by staff to determine sales potential and inventory requirements and monitor the preferences of customers.', 4, 148270, 4.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-2032.00', 'Public Relations Managers', 'Plan, direct, or coordinate activities designed to create or maintain a favorable public image or raise issue awareness for their organization or client.', 4, 146910, 5.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-2033.00', 'Fundraising Managers', 'Plan, direct, or coordinate activities to solicit and maintain funds for special projects or nonprofit organizations.', 4, 125470, 5.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3012.00', 'Administrative Services Managers', 'Plan, direct, or coordinate one or more administrative services of an organization, such as records and information management, mail distribution, and other office support services.', 3, 114130, 5.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3013.00', 'Facilities Managers', 'Plan, direct, or coordinate operations and functionalities of facilities and buildings. May include surrounding grounds or multiple facilities of an organization''s campus.', 3, 106660, 4.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3013.01', 'Security Managers', 'Direct an organization''s security functions, including physical security and safety of employees and facilities.', 4, 106660, 4.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3021.00', 'Computer and Information Systems Managers', 'Plan, direct, or coordinate activities in such fields as electronic data processing, information systems, systems analysis, and computer programming.', 4, 175140, 15.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3031.00', 'Financial Managers', 'Plan, direct, or coordinate accounting, investing, banking, insurance, securities, and other financial activities of a branch, office, or department of an establishment.', 4, 166570, 9.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3031.01', 'Treasurers and Controllers', 'Direct financial activities, such as planning, procurement, and investments for all or part of an organization.', 4, 166570, 9.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3031.03', 'Investment Fund Managers', 'Plan, direct, or coordinate investment strategy or operations for a large pool of liquid assets supplied by institutional investors or individual investors.', 5, 166570, 9.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3051.00', 'Industrial Production Managers', 'Plan, direct, or coordinate the work activities and resources necessary for manufacturing products in accordance with cost, quality, and quantity specifications.', 4, 126060, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3051.01', 'Quality Control Systems Managers', 'Plan, direct, or coordinate quality assurance programs. Formulate quality control policies and control quality of laboratory and production efforts.', 4, 126060, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3051.02', 'Geothermal Production Managers', 'Manage operations at geothermal power generation facilities. Maintain and monitor geothermal plant equipment for efficient and safe plant operations.', 3, 126060, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3051.03', 'Biofuels Production Managers', 'Manage biofuels production and plant operations. Collect and process information on plant production and performance, diagnose problems, and design corrective procedures.', 4, 126060, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3051.04', 'Biomass Power Plant Managers', 'Manage operations at biomass power generation facilities. Direct work activities at plant, including supervision of operations and maintenance staff.', 4, 126060, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3051.06', 'Hydroelectric Production Managers', 'Manage operations at hydroelectric power generation facilities. Maintain and monitor hydroelectric plant equipment for efficient and safe plant operations.', 3, 126060, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3061.00', 'Purchasing Managers', 'Plan, direct, or coordinate the activities of buyers, purchasing officers, and related workers involved in purchasing materials, products, and services. Includes wholesale or retail trade merchandising managers and procurement managers.', 4, 148080, 4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3071.00', 'Transportation, Storage, and Distribution Managers', 'Plan, direct, or coordinate transportation, storage, or distribution activities in accordance with organizational policies and applicable government laws or regulations. Includes logistics managers.', 4, 107230, 6.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3071.04', 'Supply Chain Managers', 'Direct or coordinate production, purchasing, warehousing, distribution, or financial forecasting services or activities to limit costs and improve accuracy, customer service, or safety. Examine existing procedures or opportunities for streamlining activities to meet product distribution needs. Direct the movement, storage, or processing of inventory.', 4, 107230, 6.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3111.00', 'Compensation and Benefits Managers', 'Plan, direct, or coordinate compensation and benefits activities of an organization.', 4, 149230, 1.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3121.00', 'Human Resources Managers', 'Plan, direct, or coordinate human resources activities and staff of an organization.', 4, 149280, 5.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-3131.00', 'Training and Development Managers', 'Plan, direct, or coordinate the training and development activities and staff of an organization.', 4, 133000, 6.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9013.00', 'Farmers, Ranchers, and Other Agricultural Managers', 'Plan, direct, or coordinate the management or operation of farms, ranches, greenhouses, aquacultural operations, nurseries, timber tracts, or other agricultural establishments. May hire, train, and supervise farm workers or contract for services to carry out the day-to-day activities of the managed operation. May engage in or supervise planting, cultivating, harvesting, and financial and marketing activities.', 4, 89900, -3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9021.00', 'Construction Managers', 'Plan, direct, or coordinate, usually through subordinate supervisory personnel, activities concerned with the construction and maintenance of structures, facilities, and systems. Participate in the conceptual development of a construction project and oversee its organization, scheduling, budgeting, and implementation. Includes managers in specialized construction fields, such as carpentry or plumbing.', 4, 114990, 9.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9031.00', 'Education and Childcare Administrators, Preschool and Daycare', 'Plan, direct, or coordinate academic or nonacademic activities of preschools or childcare centers and programs, including before- and after-school care.', 4, 59300, -3.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9032.00', 'Education Administrators, Kindergarten through Secondary', 'Plan, direct, or coordinate the academic, administrative, or auxiliary activities of kindergarten, elementary, or secondary schools.', 5, 105870, -0.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9033.00', 'Education Administrators, Postsecondary', 'Plan, direct, or coordinate student instruction, administration, and services, as well as other research and educational activities, at postsecondary institutions, including universities, colleges, and junior and community colleges.', 5, 104590, 1.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9041.00', 'Architectural and Engineering Managers', 'Plan, direct, or coordinate activities in such fields as architecture and engineering or research and development in these fields.', 5, 171270, 5.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9041.01', 'Biofuels/Biodiesel Technology and Product Development Managers', 'Define, plan, or execute biofuels/biodiesel research programs that evaluate alternative feedstock and process technologies with near-term commercial potential.', 4, 171270, 5.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9072.00', 'Entertainment and Recreation Managers, Except Gambling', 'Plan, direct, or coordinate entertainment and recreational activities and operations of a recreational facility, including cruise ships and parks.', 4, 79520, 6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9081.00', 'Lodging Managers', 'Plan, direct, or coordinate activities of an organization or department that provides lodging and other accommodations.', 4, 69250, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9111.00', 'Medical and Health Services Managers', 'Plan, direct, or coordinate medical and health services in hospitals, clinics, managed care organizations, public health agencies, or similar organizations.', 4, 123860, 24.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9121.00', 'Natural Sciences Managers', 'Plan, direct, or coordinate activities in such fields as life sciences, physical sciences, mathematics, statistics, and research and development in these fields.', 5, 167220, 8.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9121.01', 'Clinical Research Coordinators', 'Plan, direct, or coordinate clinical research projects. Direct the activities of workers engaged in clinical research projects to ensure compliance with protocols and overall clinical objectives. May evaluate and analyze clinical data.', 4, 167220, 8.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9121.02', 'Water Resource Specialists', 'Design or implement programs and strategies related to water resource issues such as supply, quality, and regulatory compliance issues.', 4, 167220, 8.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9141.00', 'Property, Real Estate, and Community Association Managers', 'Plan, direct, or coordinate the selling, buying, leasing, or governance activities of commercial, industrial, or residential real estate properties. Includes managers of homeowner and condominium associations, rented or leased housing units, buildings, or land (including rights-of-way).', 4, 69990, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9151.00', 'Social and Community Service Managers', 'Plan, direct, or coordinate the activities of a social service program or community outreach organization. Oversee the program or organization''s budget and policies regarding participant involvement, program requirements, and benefits. Work may involve directing social workers, counselors, or probation officers.', 4, 80390, 7.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9161.00', 'Emergency Management Directors', 'Plan and direct disaster response or crisis management activities, provide disaster preparedness training, and prepare emergency plans and procedures for natural (e.g., hurricanes, floods, earthquakes), wartime, or technological (e.g., nuclear power plant emergencies or hazardous materials spills) disasters or hostage situations.', 4, 93330, 3.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9171.00', 'Funeral Home Managers', 'Plan, direct, or coordinate the services or resources of funeral homes. Includes activities such as determining prices for services or merchandise and managing the facilities of funeral homes.', 3, 78790, 4.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9179.01', 'Fitness and Wellness Coordinators', 'Manage or coordinate fitness and wellness programs and services. Manage and train staff of wellness specialists, health educators, or fitness instructors.', 4, 69770, 6.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9179.02', 'Spa Managers', 'Plan, direct, or coordinate activities of a spa facility. Coordinate programs, schedule and direct staff, and oversee financial activities.', 3, 69770, 6.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9199.01', 'Regulatory Affairs Managers', 'Plan, direct, or coordinate production activities of an organization to ensure compliance with regulations and standard operating procedures.', 4, 141900, 4.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9199.02', 'Compliance Managers', 'Plan, direct, or coordinate activities of an organization to ensure compliance with ethical or regulatory standards.', 4, 141900, 4.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9199.08', 'Loss Prevention Managers', 'Plan and direct policies, procedures, or systems to prevent the loss of assets. Determine risk exposure or potential liability, and develop risk control measures.', 4, 141900, 4.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9199.09', 'Wind Energy Operations Managers', 'Manage wind field operations, including personnel, maintenance activities, financial activities, and planning.', 3, 141900, 4.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9199.10', 'Wind Energy Development Managers', 'Lead or manage the development and evaluation of potential wind energy business opportunities, including environmental studies, permitting, and proposals. May also manage construction of projects.', 4, 141900, 4.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('11-9199.11', 'Brownfield Redevelopment Specialists and Site Managers', 'Plan and direct cleanup and redevelopment of contaminated properties for reuse. Does not include properties sufficiently contaminated to qualify as Superfund sites.', 4, 141900, 4.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1011.00', 'Agents and Business Managers of Artists, Performers, and Athletes', 'Represent and promote artists, performers, and athletes in dealings with current or prospective employers. May handle contract negotiation and other business matters for clients.', 4, 82890, 9.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1021.00', 'Buyers and Purchasing Agents, Farm Products', 'Purchase farm products either for further processing or resale. Includes tree farm contractors, grain brokers and market operators, grain buyers, and tobacco buyers. May negotiate contracts.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1022.00', 'Wholesale and Retail Buyers, Except Farm Products', 'Buy merchandise or commodities, other than farm products, for resale to consumers at the wholesale or retail level, including both durable and nondurable goods. Analyze past buying trends, sales records, price, and quality of merchandise to determine value and yield. Select, order, and authorize payment for merchandise according to contractual agreements. May conduct meetings with sales personnel and introduce new products. May negotiate contracts. Includes assistant wholesale and retail buyers of nonfarm products.', 3, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1023.00', 'Purchasing Agents, Except Wholesale, Retail, and Farm Products', 'Purchase machinery, equipment, tools, parts, supplies, or services necessary for the operation of an establishment. Purchase raw or semifinished materials for manufacturing. May negotiate contracts.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1031.00', 'Claims Adjusters, Examiners, and Investigators', 'Review settled claims to determine that payments and settlements are made in accordance with company practices and procedures. Confer with legal counsel on claims requiring litigation. May also settle insurance claims.', 4, 78000, -5.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1032.00', 'Insurance Appraisers, Auto Damage', 'Appraise automobile or other vehicle damage to determine repair costs for insurance claim settlement. Prepare insurance forms to indicate repair cost or cost estimates and recommendations. May seek agreement with automotive repair shop on repair costs.', 3, 78240, -8.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1041.00', 'Compliance Officers', 'Examine, evaluate, and investigate eligibility for or conformity with laws and regulations governing contract compliance of licenses and permits, and perform other compliance and enforcement inspection and analysis activities not classified elsewhere.', 4, 80730, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1041.01', 'Environmental Compliance Inspectors', 'Inspect and investigate sources of pollution to protect the public and environment and ensure conformance with Federal, State, and local regulations and ordinances.', 4, 80730, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1041.03', 'Equal Opportunity Representatives and Officers', 'Monitor and evaluate compliance with equal opportunity laws, guidelines, and policies to ensure that employment practices and contracting arrangements give equal opportunity without regard to race, religion, color, national origin, sex, age, or disability.', 4, 80730, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1041.04', 'Government Property Inspectors and Investigators', 'Investigate or inspect government property to ensure compliance with contract agreements and government regulations.', 3, 80730, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1041.06', 'Coroners', 'Direct activities such as autopsies, pathological and toxicological analyses, and inquests relating to the investigation of deaths occurring within a legal jurisdiction to determine cause of death or to fix responsibility for accidental, violent, or unexplained deaths.', 3, 80730, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1041.07', 'Regulatory Affairs Specialists', 'Coordinate and document internal regulatory processes, such as internal audits, inspections, license renewals, or registrations. May compile and prepare materials for submission to regulatory agencies.', 4, 80730, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1041.08', 'Customs Brokers', 'Prepare customs documentation and ensure that shipments meet all applicable laws to facilitate the import and export of goods. Determine and track duties and taxes payable and process payments on behalf of client. Sign documents under a power of attorney. Represent clients in meetings with customs officials and apply for duty refunds and tariff reclassifications. Coordinate transportation and storage of imported goods.', 3, 80730, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1051.00', 'Cost Estimators', 'Prepare cost estimates for product manufacturing, construction projects, or services to aid management in bidding on or determining price of product or service. May specialize according to particular service performed or type of product manufactured.', 4, 78740, -3.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1071.00', 'Human Resources Specialists', 'Recruit, screen, interview, or place individuals within an organization. May perform other activities in multiple human resources areas.', 4, 75940, 6.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1075.00', 'Labor Relations Specialists', 'Resolve disputes between workers and managers, negotiate collective bargaining agreements, or coordinate grievance procedures to handle employee complaints.', 4, 95420, 2.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1081.00', 'Logisticians', 'Analyze and coordinate the ongoing logistical functions of a firm or organization. Responsible for the entire life cycle of a product, including acquisition, distribution, internal allocation, delivery, and final disposal of resources.', 4, 82320, 17.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1081.01', 'Logistics Engineers', 'Design or analyze operational solutions for projects such as transportation optimization, network modeling, process and methods analysis, cost containment, capacity enhancement, routing and shipment optimization, or information management.', 4, 82320, 17.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1081.02', 'Logistics Analysts', 'Analyze product delivery or supply chain processes to identify or recommend changes. May manage route activity including invoicing, electronic bills, and shipment tracing.', 4, 82320, 17.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1082.00', 'Project Management Specialists', 'Analyze and coordinate the schedule, timeline, procurement, staffing, and budget of a product or service on a per project basis. Lead and guide the work of technical staff. May serve as a point of contact for the client or customer.', 4, 102320, 6.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1111.00', 'Management Analysts', 'Conduct organizational studies and evaluations, design systems and procedures, conduct work simplification and measurement studies, and prepare operations and procedures manuals to assist management in operating more efficiently and effectively. Includes program analysts and management consultants.', 4, 101860, 10.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1121.00', 'Meeting, Convention, and Event Planners', 'Coordinate activities of staff, convention personnel, or clients to make arrangements for group meetings, events, or conventions.', 4, 61160, 5.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1131.00', 'Fundraisers', 'Organize activities to raise funds or otherwise solicit and gather monetary donations or other gifts for an organization. May design and produce promotional materials. May also raise awareness of the organization''s work, goals, and financial needs.', 4, 72550, 5.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1141.00', 'Compensation, Benefits, and Job Analysis Specialists', 'Conduct programs of compensation and benefits and job analysis for employer. May specialize in specific areas, such as position classification and pension programs.', 4, 78210, 6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1151.00', 'Training and Development Specialists', 'Design or conduct work-related training and development programs to improve individual skills or organizational performance. May analyze organizational training needs or evaluate training effectiveness.', 4, 69280, 10.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1161.00', 'Market Research Analysts and Marketing Specialists', 'Research conditions in local, regional, national, or online markets. Gather information to determine potential sales of a product or service, or plan a marketing or advertising campaign. May gather information on competitors, prices, sales, and methods of marketing and distribution. May employ search marketing tactics, analyze web metrics, and develop recommendations to increase search engine ranking and visibility to target markets.', 4, 78760, 7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1161.01', 'Search Marketing Strategists', 'Employ search marketing tactics to increase visibility and engagement with content, products, or services in Internet-enabled devices or interfaces. Examine search query behaviors on general or specialty search engines or other Internet-based content. Analyze research, data, or technology to understand user intent and measure outcomes for ongoing optimization.', 4, 78760, 7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1199.04', 'Business Continuity Planners', 'Develop, maintain, or implement business continuity and disaster recovery strategies and solutions, including risk assessments, business impact analyses, strategy selection, and documentation of business continuity and disaster recovery procedures. Plan, conduct, and debrief regular mock-disaster exercises to test the adequacy of existing plans and strategies, updating procedures and plans regularly. Act as a coordinator for continuity efforts after a disruption event.', 4, 83050, 3.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1199.05', 'Sustainability Specialists', 'Address organizational sustainability issues, such as waste stream management, green building practices, and green procurement plans.', 4, 83050, 3.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1199.06', 'Online Merchants', 'Conduct retail activities of businesses operating exclusively online. May perform duties such as preparing business strategies, buying merchandise, managing inventory, implementing marketing activities, fulfilling and shipping online orders, and balancing financial records.', 4, 83050, 3.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-1199.07', 'Security Management Specialists', 'Conduct security assessments for organizations, and design security systems and processes. May specialize in areas such as physical security or the safety of employees and facilities.', 4, 83050, 3.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2011.00', 'Accountants and Auditors', 'Examine, analyze, and interpret accounting records to prepare financial statements, give advice, or audit and evaluate statements prepared by others. Install or advise on systems of recording costs or other financial and budgetary data.', 4, 83680, 5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2022.00', 'Appraisers of Personal and Business Property', 'Appraise and estimate the fair value of tangible personal or business property, such as jewelry, art, antiques, collectibles, and equipment. May also appraise land.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2023.00', 'Appraisers and Assessors of Real Estate', 'Appraise real estate, exclusively, and estimate its fair value. May assess taxes in accordance with prescribed schedules.', 4, null, null, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2031.00', 'Budget Analysts', 'Examine budget estimates for completeness, accuracy, and conformance with procedures and regulations. Analyze budgeting and accounting reports.', 4, 91640, 1.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2041.00', 'Credit Analysts', 'Analyze credit data and financial statements of individuals or firms to determine the degree of risk involved in extending credit or lending money. Prepare reports with credit information for use in decisionmaking.', 4, 83510, -4.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2051.00', 'Financial and Investment Analysts', 'Conduct quantitative analyses of information involving investment programs or financial data of public or private institutions, including valuation of businesses.', 4, 102740, 7.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2052.00', 'Personal Financial Advisors', 'Advise clients on financial plans using knowledge of tax and investment strategies, securities, insurance, pension plans, and real estate. Duties include assessing clients'' assets, liabilities, cash flow, insurance coverage, tax status, and financial objectives. May also buy and sell financial assets for clients.', 4, 105070, 1.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2053.00', 'Insurance Underwriters', 'Review individual applications for insurance to evaluate degree of risk involved and determine acceptance of applications.', 4, 81370, -3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2054.00', 'Financial Risk Specialists', 'Analyze and measure exposure to credit and market risk threatening the assets, earning capacity, or economic state of an organization. May make recommendations to limit risk.', 4, 117330, 7.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2061.00', 'Financial Examiners', 'Enforce or ensure compliance with laws and regulations governing financial and securities institutions and financial and real estate transactions. May examine, verify, or authenticate records.', 4, 94160, 9.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2071.00', 'Credit Counselors', 'Advise and educate individuals or organizations on acquiring and managing debt. May provide guidance in determining the best type of loan and explain loan requirements or restrictions. May help develop debt management plans or student financial aid packages. May advise on credit issues, or provide budget, mortgage, bankruptcy, or student financial aid counseling.', 4, 52230, 3.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2072.00', 'Loan Officers', 'Evaluate, authorize, or recommend approval of commercial, real estate, or credit loans. Advise borrowers on financial status and payment methods. Includes mortgage loan officers and agents, collection analysts, loan servicing officers, loan underwriters, and payday loan officers.', 4, 76690, 1.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2081.00', 'Tax Examiners and Collectors, and Revenue Agents', 'Determine tax liability or collect taxes from individuals or business firms according to prescribed laws and regulations.', 3, 62370, -1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2082.00', 'Tax Preparers', 'Prepare tax returns for individuals or small businesses.', 3, 54920, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2099.01', 'Financial Quantitative Analysts', 'Develop quantitative techniques to inform securities investing, equities investing, pricing, or valuation of financial instruments. Develop mathematical or statistical models for risk management, asset optimization, pricing, or relative value analysis.', 5, 81100, 4.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('13-2099.04', 'Fraud Examiners, Investigators and Analysts', 'Obtain evidence, take statements, produce reports, and testify to findings regarding resolution of fraud allegations. May coordinate fraud detection and prevention activities.', 4, 81100, 4.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1211.00', 'Computer Systems Analysts', 'Analyze science, engineering, business, and other data processing problems to develop and implement solutions to complex applications problems, system administration issues, or network concerns. Perform systems management and integration functions, improve existing computer systems, and review computer system capabilities, workflow, and schedule limitations. May analyze or recommend commercially available software.', 4, 105850, 7.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1211.01', 'Health Informatics Specialists', 'Apply knowledge of nursing and informatics to assist in the design, development, and ongoing modification of computerized health care systems. May educate staff and assist in problem solving to promote the implementation of the health care system.', 5, 105850, 7.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2'])
insert into occupations (code, title, description, job_zone, median_wage, growth_pct, source_ids) values
  ('15-1212.00', 'Information Security Analysts', 'Plan, implement, upgrade, or monitor security measures for the protection of computer networks and information. Assess system vulnerabilities for security risks and propose and implement risk mitigation strategies. May ensure appropriate security controls are in place that will safeguard digital files and vital electronic infrastructure. May respond to computer security breaches and viruses.', 4, 129180, 21, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1221.00', 'Computer and Information Research Scientists', 'Conduct research into fundamental computer and information science as theorists, designers, or inventors. Develop solutions to problems in the field of computer hardware and software.', 5, 140300, 21.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1231.00', 'Computer Network Support Specialists', 'Analyze, test, troubleshoot, and evaluate existing network systems, such as local area networks (LAN), wide area networks (WAN), cloud networks, servers, and other data communications networks. Perform network maintenance to ensure networks operate correctly with minimal interruption.', 4, 76220, 1.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1232.00', 'Computer User Support Specialists', 'Provide technical assistance to computer users. Answer questions or resolve computer problems for clients in person, via telephone, or electronically. May provide assistance concerning the use of computer hardware and software, including printing, installation, word processing, electronic mail, and operating systems.', 3, 61860, -3.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1241.00', 'Computer Network Architects', 'Design and implement computer and information networks, such as local area networks (LAN), wide area networks (WAN), intranets, extranets, and other data communications networks. Perform network modeling, analysis, and planning, including analysis of capacity needs for network infrastructures. May also design network and computer security measures. May research and recommend network and data communications hardware and software.', 4, 134050, 7.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1241.01', 'Telecommunications Engineering Specialists', 'Design or configure wired, wireless, and satellite communications systems for voice, video, and data services. Supervise installation, service, and maintenance.', 3, 134050, 7.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1242.00', 'Database Administrators', 'Administer, test, and implement computer databases, applying knowledge of database management systems. Coordinate changes to computer databases. Identify, investigate, and resolve database performance issues, database capacity, and database scalability. May plan, coordinate, and implement security measures to safeguard computer databases.', 4, 104620, -0.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1243.00', 'Database Architects', 'Design strategies for enterprise databases, data warehouse systems, and multidimensional networks. Set standards for database operations, programming, query processes, and security. Model, design, and construct large relational databases or data warehouses. Create and optimize data models for warehouse infrastructure and workflow. Integrate new systems with existing warehouse structure and refine system performance and functionality.', 4, 139500, 9.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1243.01', 'Data Warehousing Specialists', 'Design, model, or implement corporate data warehousing activities. Program and configure warehouses of database information and provide support to warehouse users.', 4, 139500, 9.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1244.00', 'Network and Computer Systems Administrators', 'Install, configure, and maintain an organization''s local area network (LAN), wide area network (WAN), data communications network, operating systems, and physical and virtual servers. Perform system monitoring and verify the integrity and availability of hardware, network, and server resources and systems. Review system and application logs and verify completion of scheduled jobs, including system backups. Analyze network and server resource consumption and control user access. Install and upgrade software and maintain software licenses. May assist in network modeling, analysis, planning, and coordination between network and data communications hardware and software.', 3, 99130, -4.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1251.00', 'Computer Programmers', 'Create, modify, and test the code and scripts that allow computer applications to run. Work from specifications drawn up by software and web developers or other individuals. May develop and write computer programs to store, locate, and retrieve specific documents, data, and information.', 4, 100390, -7.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1252.00', 'Software Developers', 'Research, design, and develop computer and network software or specialized utility programs. Analyze user needs and develop software solutions, applying principles and techniques of computer science, engineering, and mathematical analysis. Update software or enhance existing software capabilities. May work with computer hardware engineers to integrate hardware and software systems, and develop specifications and performance requirements. May maintain databases within an application area, working individually or coordinating database development as part of a team.', 4, 135980, 10.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1253.00', 'Software Quality Assurance Analysts and Testers', 'Develop and execute software tests to identify software problems and their causes. Test system modifications to prepare for implementation. Document software and application defects using a bug tracking system and report defects to software or web developers. Create and maintain databases of known defects. May participate in software design reviews to provide input on functional requirements, operational characteristics, product designs, and schedules.', 4, 104300, 5.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1254.00', 'Web Developers', 'Develop and implement websites, web applications, application databases, and interactive web interfaces. Evaluate code to ensure that it is properly structured, meets industry standards, and is compatible with browsers and devices. Optimize website performance, scalability, and server-side code and processes. May develop website infrastructure and integrate websites with other computer applications.', 3, 92650, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1255.00', 'Web and Digital Interface Designers', 'Design digital user interfaces or websites. Develop and test layouts, interfaces, functionality, and navigation menus to ensure compatibility and usability across browsers or devices. May use web framework applications as well as client-side code and processes. May evaluate web design following web and accessibility standards, and may analyze web use metrics and optimize websites for marketability and search engine ranking. May design and test interfaces that facilitate the human-computer interaction and maximize the usability of digital devices, websites, and software with a focus on aesthetics and design. May create graphics used in websites and manage website content and links.', 4, 104000, 6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1255.01', 'Video Game Designers', 'Design core features of video games. Specify innovative game and role-play mechanics, story lines, and character biographies. Create and maintain design documentation. Guide and collaborate with production staff to produce games as designed.', 4, 104000, 6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.01', 'Web Administrators', 'Manage web environment design, deployment, development and maintenance activities. Perform testing and quality assurance of web sites and web applications.', 4, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.02', 'Geographic Information Systems Technologists and Technicians', 'Assist scientists or related professionals in building, maintaining, modifying, or using geographic information systems (GIS) databases. May also perform some custom application development or provide user support.', 4, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.03', 'Document Management Specialists', 'Implement and administer enterprise-wide document management systems and related procedures that allow organizations to capture, store, retrieve, share, and destroy electronic records and documents.', 4, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.04', 'Penetration Testers', 'Evaluate network system security by conducting simulated internal and external cyberattacks using adversary tools and techniques. Attempt to breach and exploit critical systems and gain access to sensitive information to assess system security.', 4, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.05', 'Information Security Engineers', 'Develop and oversee the implementation of information security procedures and policies. Build, maintain and upgrade security technology, such as firewalls, for the safe use of computer networks and the transmission and retrieval of information. Design and implement appropriate security controls to identify vulnerabilities and protect digital files and electronic infrastructures. Monitor and respond to computer security breaches, viruses, and intrusions, and perform forensic investigation. May oversee the assessment of information security systems.', 4, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.06', 'Digital Forensics Analysts', 'Conduct investigations on computer-based crimes establishing documentary or physical evidence, such as digital media and logs associated with cyber intrusion incidents. Analyze digital evidence and investigate computer security incidents to derive information in support of system and network vulnerability mitigation. Preserve and present computer-related evidence in support of criminal, fraud, counterintelligence, or law enforcement investigations.', 4, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.07', 'Blockchain Engineers', 'Maintain and support distributed and decentralized blockchain-based networks or block-chain applications such as cryptocurrency exchange, payment processing, document sharing, and digital voting. Design and deploy secure block-chain design patterns and solutions over geographically distributed networks using advanced technologies. May assist with infrastructure setup and testing for application transparency and security.', 4, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.08', 'Computer Systems Engineers/Architects', 'Design and develop solutions to complex applications problems, system administration issues, or network concerns. Perform systems management and integration functions.', 3, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-1299.09', 'Information Technology Project Managers', 'Plan, initiate, and manage information technology (IT) projects. Lead and guide the work of technical staff. Serve as liaison between business and technical aspects of projects. Plan project stages and assess business implications for each stage. Monitor progress to assure deadlines, standards, and cost targets are met.', 4, 116580, 5.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2011.00', 'Actuaries', 'Analyze statistical data, such as mortality, accident, sickness, disability, and retirement rates and construct probability tables to forecast risk and liability for payment of future benefits. May ascertain insurance rates required and cash reserves necessary to ensure payment of future benefits.', 4, 130000, 9.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2021.00', 'Mathematicians', 'Conduct research in fundamental mathematics or in application of mathematical techniques to science, management, and other fields. Solve problems in various fields using mathematical methods.', 5, 126710, 0.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2031.00', 'Operations Research Analysts', 'Formulate and apply mathematical modeling and other optimizing methods to develop and interpret information that assists management with decisionmaking, policy formulation, or other managerial functions. May collect and analyze data and develop decision support software, services, or products. May develop and supply optimal time, cost, or logistics networks for program evaluation, review, or implementation.', 5, 88940, 11.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2041.00', 'Statisticians', 'Develop or apply mathematical or statistical theory and methods to collect, organize, interpret, and summarize numerical data to provide usable information. May specialize in fields such as biostatistics, agricultural statistics, business statistics, or economic statistics. Includes mathematical and survey statisticians.', 5, 105650, 11, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2041.01', 'Biostatisticians', 'Develop and apply biostatistical theory and methods to the study of life sciences.', 5, 105650, 11, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2051.00', 'Data Scientists', 'Develop and implement a set of techniques or analytics applications to transform raw data into meaningful information using data-oriented programming languages and visualization software. Apply data mining, data modeling, natural language processing, and machine learning to extract and analyze information from large structured and unstructured datasets. Visualize, interpret, and report data findings. May create dynamic data reports.', 4, 120230, 34.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2051.01', 'Business Intelligence Analysts', 'Produce financial and market intelligence by querying data repositories and generating periodic reports. Devise methods for identifying data patterns and trends in available information sources.', 4, 120230, 34.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2051.02', 'Clinical Data Managers', 'Apply knowledge of health care and database management to analyze clinical data, and to identify and report trends.', 4, 120230, 34.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('15-2099.01', 'Bioinformatics Technicians', 'Apply principles and methods of bioinformatics to assist scientists in areas such as pharmaceuticals, medical technology, biotechnology, computational biology, proteomics, computer information science, biology and medical informatics. Apply bioinformatics tools to visualize, analyze, manipulate or interpret molecular data. May build and maintain databases for processing and analyzing genomic or other biological information.', 4, 81490, 7.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-1011.00', 'Architects, Except Landscape and Naval', 'Plan and design structures, such as private residences, office buildings, theaters, factories, and other structural property.', 5, 99280, 4.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-1012.00', 'Landscape Architects', 'Plan and design land areas for projects such as parks and other recreational facilities, airports, highways, hospitals, schools, land subdivisions, and commercial, industrial, and residential sites.', 4, 79870, 4.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-1021.00', 'Cartographers and Photogrammetrists', 'Research, study, and prepare maps and other spatial data in digital or graphic form for one or more purposes, such as legal, social, political, educational, and design purposes. May work with Geographic Information Systems (GIS). May design and evaluate algorithms, data structures, and user interfaces for GIS and mapping systems. May collect, analyze, and interpret geographic information provided by geodetic surveys, aerial photographs, and satellite data.', 4, 81390, 7.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-1022.00', 'Surveyors', 'Make exact measurements and determine property boundaries. Provide data relevant to the shape, contour, gravitation, location, elevation, or dimension of land or land features on or near the earth''s surface for engineering, mapmaking, mining, land evaluation, construction, and other purposes.', 4, 75440, 5.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-1022.01', 'Geodetic Surveyors', 'Measure large areas of the Earth''s surface using satellite observations, global navigation satellite systems (GNSS), light detection and ranging (LIDAR), or related sources.', 4, 75440, 5.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2011.00', 'Aerospace Engineers', 'Perform engineering duties in designing, constructing, and testing aircraft, missiles, and spacecraft. May conduct basic and applied research to evaluate adaptability of materials and equipment to aircraft design and manufacture. May recommend improvements in testing equipment and techniques.', 4, 134960, 8.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2021.00', 'Agricultural Engineers', 'Apply knowledge of engineering technology and biological science to agricultural problems concerned with power and machinery, electrification, structures, soil and water conservation, and processing of agricultural products.', 4, 98590, 6.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2031.00', 'Bioengineers and Biomedical Engineers', 'Apply knowledge of engineering, biology, chemistry, computer science, and biomechanical principles to the design, development, and evaluation of biological, agricultural, and health systems and products, such as artificial organs, prostheses, instrumentation, medical information systems, and health management and care delivery systems.', 4, 109370, 7.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2041.00', 'Chemical Engineers', 'Design chemical plant equipment and devise processes for manufacturing chemicals and products, such as gasoline, synthetic rubber, plastics, detergents, cement, paper, and pulp, by applying principles and technology of chemistry, physics, and engineering.', 4, 125040, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2051.00', 'Civil Engineers', 'Perform engineering duties in planning, designing, and overseeing construction and maintenance of building structures and facilities, such as roads, railroads, airports, bridges, harbors, channels, dams, irrigation projects, pipelines, power plants, and water and sewage systems.', 4, 100840, 6.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2051.01', 'Transportation Engineers', 'Develop plans for surface transportation projects, according to established engineering standards and state or federal construction policy. Prepare designs, specifications, or estimates for transportation facilities. Plan modifications of existing streets, highways, or freeways to improve traffic flow.', 4, 100840, 6.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2051.02', 'Water/Wastewater Engineers', 'Design or oversee projects involving provision of potable water, disposal of wastewater and sewage, or prevention of flood-related damage. Prepare environmental documentation for water resources, regulatory program compliance, data management and analysis, and field work. Perform hydraulic modeling and pipeline design.', 4, 100840, 6.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2061.00', 'Computer Hardware Engineers', 'Research, design, develop, or test computer or computer-related equipment for commercial, industrial, military, or scientific use. May supervise the manufacturing and installation of computer or computer-related equipment and components.', 4, 161740, 9.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2071.00', 'Electrical Engineers', 'Research, design, develop, test, or supervise the manufacturing and installation of electrical equipment, components, or systems for commercial, industrial, military, or scientific use.', 4, 120630, 9.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2072.00', 'Electronics Engineers, Except Computer', 'Research, design, develop, or test electronic components and systems for commercial, industrial, military, or scientific use employing knowledge of electronic theory and materials properties. Design electronic circuits and components for use in fields such as telecommunications, aerospace guidance and propulsion control, acoustics, or instruments and controls.', 4, 130220, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2072.01', 'Radio Frequency Identification Device Specialists', 'Design and implement radio frequency identification device (RFID) systems used to track shipments or goods.', 4, 130220, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2081.00', 'Environmental Engineers', 'Research, design, plan, or perform engineering duties in the prevention, control, and remediation of environmental hazards using various engineering disciplines. Work may include waste treatment, site remediation, or pollution control technology.', 4, 107110, 6.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2111.00', 'Health and Safety Engineers, Except Mining Safety Engineers and Inspectors', 'Promote worksite or product safety by applying knowledge of industrial processes, mechanics, chemistry, psychology, and industrial health and safety laws. Includes industrial product safety engineers.', 4, 115160, 5.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2111.02', 'Fire-Prevention and Protection Engineers', 'Research causes of fires, determine fire protection methods, and design or recommend materials or equipment such as structural components or fire-detection equipment to assist organizations in safeguarding life and property against fire, explosion, and related hazards.', 4, 115160, 5.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2112.00', 'Industrial Engineers', 'Design, develop, test, and evaluate integrated systems for managing industrial production processes, including human work factors, quality control, inventory control, logistics and material flow, cost analysis, and production coordination.', 4, 102440, 12.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2112.01', 'Human Factors Engineers and Ergonomists', 'Design objects, facilities, and environments to optimize human well-being and overall system performance, applying theory, principles, and data regarding the relationship between humans and respective technology. Investigate and analyze characteristics of human behavior and performance as it relates to the use of technology.', 5, 102440, 12.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2112.02', 'Validation Engineers', 'Design or plan protocols for equipment or processes to produce products meeting internal and external purity, safety, and quality requirements.', 4, 102440, 12.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2112.03', 'Manufacturing Engineers', 'Design, integrate, or improve manufacturing systems or related processes. May work with commercial or industrial designers to refine product designs to increase producibility and decrease costs.', 4, 102440, 12.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2121.00', 'Marine Engineers and Naval Architects', 'Design, develop, and evaluate the operation of marine vessels, ship machinery, and related equipment, such as power supply and propulsion systems.', 4, 112230, 6.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2131.00', 'Materials Engineers', 'Evaluate materials and develop machinery and processes to manufacture materials for use in products that must meet specialized design and performance specifications. Develop new uses for known materials. Includes those engineers working with composite materials or specializing in one type of material, such as graphite, metal and metal alloys, ceramics and glass, plastics and polymers, and naturally occurring materials. Includes metallurgists and metallurgical engineers, ceramic engineers, and welding engineers.', 4, 112860, 7.5, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2141.00', 'Mechanical Engineers', 'Perform engineering duties in planning and designing tools, engines, machines, and other mechanically functioning equipment. Oversee installation, operation, maintenance, and repair of equipment such as centralized heat, gas, water, and steam systems.', 4, 104110, 11.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2141.01', 'Fuel Cell Engineers', 'Design, evaluate, modify, or construct fuel cell components or systems for transportation, stationary, or portable applications.', 4, 104110, 11.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2141.02', 'Automotive Engineers', 'Develop new or improved designs for vehicle structural members, engines, transmissions, or other vehicle systems, using computer-assisted design technology. Direct building, modification, or testing of vehicle or components.', 4, 104110, 11.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2151.00', 'Mining and Geological Engineers, Including Mining Safety Engineers', 'Conduct subsurface surveys to identify the characteristics of potential land or mining development sites. May specify the ground support systems, processes, and equipment for safe, economical, and environmentally sound extraction or underground construction activities. May inspect areas for unsafe geological conditions, equipment, and working conditions. May design, implement, and coordinate mine safety programs.', 4, 106220, 3.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2161.00', 'Nuclear Engineers', 'Conduct research on nuclear engineering projects or apply principles and theory of nuclear science to problems concerned with release, control, and use of nuclear energy and nuclear waste disposal.', 4, 133970, 0.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2171.00', 'Petroleum Engineers', 'Devise methods to improve oil and gas extraction and production and determine the need for new or modified tool designs. Oversee drilling and offer technical advice.', 4, 144910, 2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2199.03', 'Energy Engineers, Except Wind and Solar', 'Design, develop, or evaluate energy-related projects or programs to reduce energy costs or improve energy efficiency during the designing, building, or remodeling stages of construction. May specialize in electrical systems; heating, ventilation, and air-conditioning (HVAC) systems; green buildings; lighting; air quality; or energy procurement.', 4, 122930, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2199.05', 'Mechatronics Engineers', 'Research, design, develop, or test automation, intelligent systems, smart devices, or industrial systems control.', 4, 122930, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2199.06', 'Microsystems Engineers', 'Research, design, develop, or test microelectromechanical systems (MEMS) devices.', 5, 122930, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2199.07', 'Photonics Engineers', 'Design technologies specializing in light information or light energy, such as laser or fiber optics technology.', 4, 122930, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2199.08', 'Robotics Engineers', 'Research, design, develop, or test robotic applications.', 4, 122930, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2199.09', 'Nanosystems Engineers', 'Design, develop, or supervise the production of materials, devices, or systems of unique molecular or macromolecular composition, applying principles of nanoscale physics and electrical, chemical, or biological engineering.', 5, 122930, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2199.10', 'Wind Energy Engineers', 'Design underground or overhead wind farm collector systems and prepare and develop site specifications.', 4, 122930, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-2199.11', 'Solar Energy Systems Engineers', 'Perform site-specific engineering analysis or evaluation of energy efficiency and solar projects involving residential, commercial, or industrial customers. Design solar domestic hot water and space heating systems for new and existing structures, applying knowledge of structural energy requirements, local climates, solar technology, and thermodynamics.', 4, 122930, 3.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3011.00', 'Architectural and Civil Drafters', 'Prepare detailed drawings of architectural and structural features of buildings or drawings and topographical relief maps used in civil engineering projects, such as highways, bridges, and public works. Use knowledge of building materials, engineering practices, and mathematics to complete drawings.', 3, 66150, 5.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3012.00', 'Electrical and Electronics Drafters', 'Prepare wiring diagrams, circuit board assembly diagrams, and layout drawings used for the manufacture, installation, or repair of electrical equipment.', 3, 76870, -3.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3013.00', 'Mechanical Drafters', 'Prepare detailed working diagrams of machinery and mechanical devices, including dimensions, fastening methods, and other engineering information.', 3, 71550, -6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3021.00', 'Aerospace Engineering and Operations Technologists and Technicians', 'Operate, install, adjust, and maintain integrated computer/communications systems, consoles, simulators, and other data acquisition, test, and measurement instruments and equipment, which are used to launch, track, position, and evaluate air and space vehicles. May record and interpret test data.', 3, 82890, 11.9, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3022.00', 'Civil Engineering Technologists and Technicians', 'Apply theory and principles of civil engineering in planning, designing, and overseeing construction and maintenance of structures and facilities under the direction of engineering staff or physical scientists.', 3, 64950, 3.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3023.00', 'Electrical and Electronic Engineering Technologists and Technicians', 'Apply electrical and electronic theory and related knowledge, usually under the direction of engineering staff, to design, build, repair, adjust, and modify electrical components, circuitry, controls, and machinery for subsequent evaluation and use by engineering staff in making engineering design decisions.', 3, 78190, 2.4, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3024.00', 'Electro-Mechanical and Mechatronics Technologists and Technicians', 'Operate, test, maintain, or adjust unmanned, automated, servomechanical, or electromechanical equipment. May operate unmanned submarines, aircraft, or other equipment to observe or record visual information at sites such as oil rigs, crop fields, buildings, or for similar infrastructure, deep ocean exploration, or hazardous waste removal. May assist engineers in testing and designing robotics equipment.', 3, 73900, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3024.01', 'Robotics Technicians', 'Build, install, test, or maintain robotic equipment or related automated production systems.', 3, 73900, 2.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3025.00', 'Environmental Engineering Technologists and Technicians', 'Apply theory and principles of environmental engineering to modify, test, and operate equipment and devices used in the prevention, control, and remediation of environmental problems, including waste treatment and site remediation, under the direction of engineering staff or scientists. May assist in the development of environmental remediation devices.', 4, 59920, 3.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3026.00', 'Industrial Engineering Technologists and Technicians', 'Apply engineering theory and principles to problems of industrial layout or manufacturing production, usually under the direction of engineering staff. May perform time and motion studies on worker operations in a variety of industries for purposes such as establishing standard production rates or improving efficiency.', 3, 66120, 3.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3026.01', 'Nanotechnology Engineering Technologists and Technicians', 'Implement production processes and operate commercial-scale production equipment to produce, test, or modify materials, devices, or systems of unique molecular or macromolecular composition. Operate advanced microscopy equipment to manipulate nanoscale objects. Work under the supervision of nanoengineering staff.', 4, 66120, 3.1, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3027.00', 'Mechanical Engineering Technologists and Technicians', 'Apply theory and principles of mechanical engineering to modify, develop, test, or adjust machinery and equipment under direction of engineering staff or physical scientists.', 3, 74510, 1.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3027.01', 'Automotive Engineering Technicians', 'Assist engineers in determining the practicality of proposed product design changes and plan and carry out tests on experimental test devices or equipment for performance, durability, or efficiency.', 3, 74510, 1.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3028.00', 'Calibration Technologists and Technicians', 'Execute or adapt procedures and techniques for calibrating measurement devices, by applying knowledge of measurement science, mathematics, physics, chemistry, and electronics, sometimes under the direction of engineering staff. Determine measurement standard suitability for calibrating measurement devices. May perform preventive maintenance on equipment. May perform corrective actions to address identified calibration problems.', 3, 67820, 4.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3029.08', 'Photonics Technicians', 'Build, install, test, or maintain optical or fiber optic equipment, such as lasers, lenses, or mirrors, using spectrometers, interferometers, or related equipment.', 3, 78350, 2.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('17-3031.00', 'Surveying and Mapping Technicians', 'Perform surveying and mapping duties, usually under the direction of an engineer, surveyor, cartographer, or photogrammetrist, to obtain data used for construction, mapmaking, boundary location, mining, or other purposes. May calculate mapmaking information and create maps from source data, such as surveying notes, aerial photography, satellite data, or other maps to show topographical features, political boundaries, and other features. May verify accuracy and completeness of maps.', 3, 54240, 5.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1011.00', 'Animal Scientists', 'Conduct research in the genetics, nutrition, reproduction, growth, and development of domestic farm animals.', 5, 68940, 5.8, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1012.00', 'Food Scientists and Technologists', 'Use chemistry, microbiology, engineering, and other sciences to study the principles underlying the processing and deterioration of foods; analyze food content to determine levels of vitamins, fat, sugar, and protein; discover new food sources; research ways to make processed foods safe, palatable, and healthful; and apply food science knowledge to determine best ways to process, package, preserve, store, and distribute food.', 4, 88720, 6.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1013.00', 'Soil and Plant Scientists', 'Conduct research in breeding, physiology, production, yield, and management of crops and agricultural plants or trees, shrubs, and nursery stock, their growth in soils, and control of pests; or study the chemical, physical, biological, and mineralogical composition of soils as they relate to plant or crop growth. May classify and map soils and investigate effects of alternative practices on soil and crop productivity.', 5, 78850, 6.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1021.00', 'Biochemists and Biophysicists', 'Study the chemical composition or physical principles of living cells and organisms, their electrical and mechanical energy, and related phenomena. May conduct research to further understanding of the complex chemical combinations and reactions involved in metabolism, reproduction, growth, and heredity. May determine the effects of foods, drugs, serums, hormones, and other substances on tissues and vital processes of living organisms.', 5, 127410, 12.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1022.00', 'Microbiologists', 'Investigate the growth, structure, development, and other characteristics of microscopic organisms, such as bacteria, algae, or fungi. Includes medical microbiologists who study the relationship between organisms and disease or the effects of antibiotics on microorganisms.', 4, 87990, 6.2, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1023.00', 'Zoologists and Wildlife Biologists', 'Study the origins, behavior, diseases, genetics, and life processes of animals and wildlife. May specialize in wildlife research and management. May collect and analyze biological data to determine the environmental effects of present and potential use of land and water habitats.', 4, 76780, 3.6, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1029.01', 'Bioinformatics Scientists', 'Conduct research using bioinformatics theory and methods in areas such as pharmaceuticals, medical technology, biotechnology, computational biology, proteomics, computer information science, biology and medical informatics. May design databases and develop algorithms for processing and analyzing genomic information, or other biological information.', 5, 98920, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1029.02', 'Molecular and Cellular Biologists', 'Research and study cellular molecules and organelles to understand cell function and organization.', 5, 98920, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1029.03', 'Geneticists', 'Research and study the inheritance of traits at the molecular, organism or population level. May evaluate or treat patients with genetic disorders.', 5, 98920, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1029.04', 'Biologists', 'Research or study basic principles of plant and animal life, such as origin, relationship, development, anatomy, and functions.', 5, 98920, 4.7, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2']),
  ('19-1031.00', 'Conservation Scientists', 'Manage, improve, and protect natural resources to maximize their use without damaging the environment. May conduct soil surveys and develop plans to eliminate soil erosion or to protect rangelands. May instruct farmers, agricultural production managers, or ranchers in best ways to use crop rotation, contour plowing, or terracing to conserve soil and water; in the number and kind of livestock and forage plants best suited to particular ranges; and in range and farm improvements, such as fencing and reservoirs for stock watering.', 4, 73010, 5.3, array['onet-31.0', 'nces-cip-soc-2020', 'bls-oews-national', 'bls-ep-table-1-2'])
